import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"远程存储（S3）","description":"MinIO / R2 / AWS S3：公开桶、私密桶、public_base_url、多节点与 Redis。","frontmatter":{"title":"远程存储（S3）","description":"MinIO / R2 / AWS S3：公开桶、私密桶、public_base_url、多节点与 Redis。"},"headers":[],"relativePath":"guide/config/s3.md","filePath":"guide/config/s3.md","lastUpdated":1790057721000}`),a={name:`guide/config/s3.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="远程存储-s3" tabindex="-1">远程存储（S3） <a class="header-anchor" href="#远程存储-s3" aria-label="Permalink to “远程存储（S3）”">​</a></h1><p>安装包很大或需要 CDN 时使用对象存储。本机磁盘足够时见 <a href="./local-storage">本机磁盘存储</a>。</p><p>兼容 MinIO、Cloudflare R2、AWS S3。<code>storage.driver: s3</code>。</p><h2 id="公钥桶-storage-s3" tabindex="-1">公钥桶 <code>storage.s3</code> <a class="header-anchor" href="#公钥桶-storage-s3" aria-label="Permalink to “公钥桶 storage.s3”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认</th><th>说明</th><th>何时改</th></tr></thead><tbody><tr><td><code>endpoint</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>API 端点</td><td>MinIO/R2 必填；AWS 可留空走默认</td></tr><tr><td><code>region</code></td><td>string</td><td><code>auto</code></td><td>区域</td><td>AWS 填真实区域；R2 可保持 <code>auto</code></td></tr><tr><td><code>bucket</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>公开产物桶</td><td><code>driver=s3</code> 时必填</td></tr><tr><td><code>access_key</code> / <code>secret_key</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>访问密钥</td><td>最小权限：Put/Get 公开对象；用环境变量注入</td></tr><tr><td><code>use_path_style</code></td><td>bool</td><td><code>true</code></td><td>路径风格</td><td>AWS 虚拟主机风格可改 false</td></tr><tr><td><code>public_base_url</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>对外下载根；空则按 endpoint+bucket 拼匿名 GET</td><td>上 CDN 时指到 CDN 源</td></tr></tbody></table><p>环境变量：<code>KIRIVERS_STORAGE_S3_*</code>、<code>KIRIVERS_STORAGE_S3_PUBLIC_BASE_URL</code>。</p><h2 id="私密桶-storage-private" tabindex="-1">私密桶 <code>storage.private</code> <a class="header-anchor" href="#私密桶-storage-private" aria-label="Permalink to “私密桶 storage.private”">​</a></h2><p>GeoIP MMDB 等敏感对象。<code>driver=s3</code> 且未配 private bucket 时 GeoIP 上传失败，<strong>不得</strong>写入公共桶。键：<code>KIRIVERS_STORAGE_PRIVATE_*</code>。</p><p>不要把安装包和 GeoIP 放进同一个桶。</p><h2 id="多节点下载" tabindex="-1">多节点下载 <a class="header-anchor" href="#多节点下载" aria-label="Permalink to “多节点下载”">​</a></h2><p>必须同时 <code>storage.driver=s3</code> 与 <code>cache.driver=redis</code>，见 <a href="./cluster">多节点</a>。</p><ul><li><code>cluster.download: s3</code>：check 给出公共对象 URL（可走 CDN）。</li><li><code>cluster.download: local</code>：应用节点代拉；check 使用 <code>private, no-store</code>。</li></ul><p>失败时看进程存储日志（<code>mod=storage</code>）。对象存储 SDK 调用不是运维步骤。</p><p>当前项目 PATCH <strong>拒绝</strong> <code>storage_visibility=private</code>。签名 URL 仍用于 local-proxy 等路径。见 <a href="/guide/features/cdn">CDN 与下载</a>。</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};